assert.ok(m8.includes('**50–100**')&&m8.includes('**250–500**'));
assert.ok(m9.includes('**30/06/2021**')&&m9.includes('**02/08/2024**')&&m9.includes('**40 %–60 %**'));
assert.ok(m10.includes('**27/12/2025**')&&m10.includes('**72 horas**')&&m10.includes('**2 meses adicionales**'));
